#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>

using namespace std;

int n, t;
char grid1[10][10], grid2[10][10];
int dist[10][10];
bool reach[60][10][10][10][10];

int dx[] = {-1, 0, 1, 0, 0};
int dy[] = {0, 1, 0, -1, 0};

inline bool valid(int x, int y) { return x >= 0 && x < n && y >= 0 && y < n; }
inline bool digit(char c) { return c >= '0' && c <= '9'; }

void bfs(int sx, int sy) {
    queue<pair<int,int>> q;
    dist[sx][sy] = 0;
    q.push({sx, sy});
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (valid(nx, ny) && digit(grid1[nx][ny]) && dist[nx][ny] == 1000) {
                dist[nx][ny] = dist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> t;
    for (int i = 0; i < n; ++i) cin >> grid1[i];
    for (int i = 0; i < n; ++i) cin >> grid2[i];

    // init dist
    for (int i = 0; i < 10; ++i)
        for (int j = 0; j < 10; ++j)
            dist[i][j] = 1000;

    // find start
    int sx, sy;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (grid1[i][j] == 'Z') { sx = i; sy = j; }

    bfs(sx, sy);

    // init reach
    memset(reach, 0, sizeof(reach));

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            for (int d = 0; d < 5; ++d) {
                int ni = i + dx[d], nj = j + dy[d];
                if (valid(ni, nj) && digit(grid1[i][j]) && digit(grid1[ni][nj]))
                    reach[0][i][j][ni][nj] = true;
            }

    for (int k = 0; k <= t - 2; ++k)
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                for (int l = 0; l < n; ++l)
                    for (int m = 0; m < n; ++m) {
                        if (!reach[k][i][j][l][m]) continue;
                        for (int d = 0; d < 5; ++d) {
                            int nl = l + dx[d], nm = m + dy[d];
                            if (valid(nl, nm) && digit(grid1[nl][nm]) && dist[l][m] >= k+2 && dist[nl][nm] >= k+2)
                                reach[k+1][i][j][nl][nm] = true;
                        }
                    }

    vector<pair<int,int>> cells;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (digit(grid1[i][j]))
                cells.push_back({i, j});

    int V = 2 * cells.size() + 2;
    vector<vector<pair<int,int>>> graph(V);

    for (int i = 0; i < (int)cells.size(); ++i) {
        int c1 = grid1[cells[i].first][cells[i].second] - '0';
        graph[0].push_back({i+1, c1});
        graph[i+1].push_back({0, 0});
        int c2 = grid2[cells[i].first][cells[i].second] - '0';
        graph[cells.size()+1+i].push_back({V-1, c2});
        graph[V-1].push_back({cells.size()+1+i, 0});
    }

    for (int i = 0; i < (int)cells.size(); ++i)
        for (int j = 0; j < (int)cells.size(); ++j) {
            bool ok = false;
            for (int k = 0; k <= t-1; ++k)
                if (reach[k][cells[i].first][cells[i].second][cells[j].first][cells[j].second]) {
                    ok = true;
                    break;
                }
            if (ok) {
                graph[i+1].push_back({cells.size()+1+j, 1000});
                graph[cells.size()+1+j].push_back({i+1, 0});
            }
        }

    int flow = 0;
    while (true) {
        vector<bool> visited(V, false);
        vector<int> parent(V, -1);
        queue<int> q;
        visited[0] = true;
        q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : graph[u]) {
                if (!visited[e.first] && e.second > 0) {
                    visited[e.first] = true;
                    parent[e.first] = u;
                    q.push(e.first);
                }
            }
        }
        if (parent[V-1] == -1) break;

        int inc = 1000;
        for (int v = V-1; v != 0; v = parent[v]) {
            int u = parent[v];
            for (auto& e : graph[u])
                if (e.first == v) inc = min(inc, e.second);
        }

        for (int v = V-1; v != 0; v = parent[v]) {
            int u = parent[v];
            for (auto& e : graph[u])
                if (e.first == v) e.second -= inc;
            for (auto& e : graph[v])
                if (e.first == u) e.second += inc;
        }
        flow += inc;
    }

    cout << flow;
    return 0;
}
